CREATE TABLE external_gateway_clients(id uuid PRIMARY KEY,node_id uuid NOT NULL REFERENCES nodes(id),name text NOT NULL,client_kind text NOT NULL CHECK(client_kind IN('chatgpt','claude','gemini','ide','agent','mcp')),client_id text NOT NULL UNIQUE,redirect_uris text[] NOT NULL DEFAULT '{}',public_client boolean NOT NULL DEFAULT true,created_by uuid REFERENCES principals(id),created_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz);
CREATE TABLE external_device_authorizations(id uuid PRIMARY KEY,client_id uuid NOT NULL REFERENCES external_gateway_clients(id),node_id uuid NOT NULL REFERENCES nodes(id),workspace_id uuid REFERENCES workspaces(id),device_code_hash char(64) NOT NULL UNIQUE,user_code_hash char(64) NOT NULL UNIQUE,requested_scopes text[] NOT NULL,library_ids uuid[] NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','denied','expired','consumed')),principal_id uuid REFERENCES principals(id),expires_at timestamptz NOT NULL,interval_seconds integer NOT NULL DEFAULT 5 CHECK(interval_seconds>=1),created_at timestamptz NOT NULL DEFAULT now(),approved_at timestamptz);
CREATE TABLE external_access_grants(id uuid PRIMARY KEY,client_id uuid NOT NULL REFERENCES external_gateway_clients(id),node_id uuid NOT NULL REFERENCES nodes(id),workspace_id uuid REFERENCES workspaces(id),principal_id uuid NOT NULL REFERENCES principals(id),scopes text[] NOT NULL,library_ids uuid[] NOT NULL DEFAULT '{}',disclosure_budget jsonb NOT NULL,token_hash char(64) NOT NULL UNIQUE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz,revoked_by uuid REFERENCES principals(id),revocation_reason text);
CREATE INDEX external_grants_active_idx ON external_access_grants(token_hash,expires_at) WHERE revoked_at IS NULL;
CREATE TABLE external_write_proposals(id uuid PRIMARY KEY,grant_id uuid NOT NULL REFERENCES external_access_grants(id),tool text NOT NULL,arguments jsonb NOT NULL,input_digest char(64) NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected','executed','expired')),proposed_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,reviewed_by uuid REFERENCES principals(id),reviewed_at timestamptz,review_comment text,executed_at timestamptz,execution_receipt jsonb);
CREATE TABLE external_access_receipts(id uuid PRIMARY KEY,grant_id uuid REFERENCES external_access_grants(id),client_id uuid NOT NULL REFERENCES external_gateway_clients(id),node_id uuid NOT NULL REFERENCES nodes(id),workspace_id uuid REFERENCES workspaces(id),principal_id uuid REFERENCES principals(id),tool text NOT NULL,scope text NOT NULL,request_digest char(64) NOT NULL,outcome text NOT NULL CHECK(outcome IN('allowed','partial','denied','error')),disclosed_resource_ids uuid[] NOT NULL DEFAULT '{}',disclosed_fragment_count integer NOT NULL DEFAULT 0,disclosed_bytes integer NOT NULL DEFAULT 0,sensitive_fragment_count integer NOT NULL DEFAULT 0,budget_snapshot jsonb NOT NULL,details jsonb NOT NULL DEFAULT '{}',occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX external_receipts_audit_idx ON external_access_receipts(node_id,principal_id,occurred_at DESC);
CREATE TABLE external_gateway_audit_history(id uuid PRIMARY KEY,node_id uuid NOT NULL REFERENCES nodes(id),client_id uuid REFERENCES external_gateway_clients(id),grant_id uuid REFERENCES external_access_grants(id),actor_principal_id uuid REFERENCES principals(id),event_type text NOT NULL CHECK(event_type IN('CLIENT_REGISTERED','DEVICE_CODE_ISSUED','AUTHORIZATION_APPROVED','AUTHORIZATION_DENIED','TOKEN_ISSUED','TOOL_ACCESSED','WRITE_PROPOSED','WRITE_APPROVED','WRITE_REJECTED','WRITE_EXECUTED','GRANT_REVOKED')),details jsonb NOT NULL DEFAULT '{}',occurred_at timestamptz NOT NULL DEFAULT now());
